  + '    ctx.lineTo(width, y + 20);\n'
  + '    ctx.stroke();\n'
  + '  }\n'
  + '}\n'
  + '\n'
  + 'function drawDots(\n'
  + '  ctx: CanvasRenderingContext2D,\n'
