  + '\n'
  + '  ctx.fillStyle = chessboardColor;\n'
  + '  for (let x = 0; x < width; x += squareSize) {\n'
  + '    for (let y = 0; y < height; y += squareSize) {\n'
  + '      const isEvenSquare = (x / squareSize + y / squareSize) % 2 === 0;\n'
  + '      if (!isEvenSquare) continue;\n'
  + '      ctx.fillRect(x, y, squareSize, squareSize);\n'
