  + 'import classNames from "classnames";\n'
  + 'import type { CSSProperties } from "react";\n'
  + 'import { useLayoutEffect, useRef } from "react";\n'
  + '\n'
  + 'import { useJss, useMode, useTheme } from "@/components/CopyUiProvider";\n'
