  + '\n'
  + 'type BackgroundKind = "dots" | "lines" | "chessboard";\n'
  + '\n'
  + 'type BackgroundConfigDots = {\n'
  + '  dotColor: string;\n'
  + '};\n'
  + '\n'
  + 'type BackgroundConfigLines = {\n'
  + '  lineColor: string;\n'
  + '};\n'
  + '\n'
  + 'type BackgroundConfigChessboard = {\n'
  + '  chessboardColor: string;\n'
  + '};\n'
  + '\n'
  + 'type BackgroundConfig<K extends BackgroundKind> = K extends "dots"\n'
  + '  ? BackgroundConfigDots\n'
  + '  : K extends "lines"\n'
  + '    ? BackgroundConfigLines\n'
  + '    : K extends "chessboard"\n'
  + '      ? BackgroundConfigChessboard\n'
  + '      : never;\n'
  + '\n'
  + 'type BackgroundProps<K extends BackgroundKind> = {\n'
  + '  className?: string;\n'
  + '  style?: CSSProperties;\n'
  + '  kind: K;\n'
  + '  config?: BackgroundConfig<K>;\n'
  + '};\n'
  + '\n'
  + 'type BackgroundComponent = {\n'
  + '  <K extends BackgroundKind>(props: BackgroundProps<K>): React.ReactNode;\n'
  + '  displayName: string;\n'
  + '  Container: typeof BackgroundContainer;\n'
  + '};\n'
  + '\n'
  + 'const Background: BackgroundComponent = <K extends BackgroundKind>(\n'
  + '  props: BackgroundProps<K>,\n'
  + ') => {\n'
  + '  const { className, style, kind, config } = props;\n'
  + '\n'
  + '  const jss = useJss();\n'
  + '  const mode = useMode();\n'
  + '  const theme = useTheme();\n'
  + '\n'
  + '  const wrapperRef = useRef<HTMLDivElement>(null);\n'
  + '  const canvasRef = useRef<HTMLCanvasElement>(null);\n'
  + '\n'
  + '  useLayoutEffect(() => {\n'
  + '    const wrapper = wrapperRef.current;\n'
  + '    const canvas = canvasRef.current;\n'
  + '    if (!wrapper || !canvas) return;\n'
  + '\n'
  + '    const ctx = canvas.getContext("2d");\n'
  + '    if (!ctx) return;\n'
  + '\n'
  + '    const resizeCanvas = () => {\n'
  + '      const dpr = window.devicePixelRatio || 1;\n'
  + '      const rect = wrapper.getBoundingClientRect();\n'
  + '\n'
  + '      canvas.width = rect.width * dpr;\n'
  + '      canvas.height = rect.height * dpr;\n'
  + '\n'
  + '      canvas.style.width = `${rect.width}px`;\n'
  + '      canvas.style.height = `${rect.height}px`;\n'
  + '\n'
  + '      ctx.scale(dpr, dpr);\n'
  + '\n'
  + '      drawBackground();\n'
  + '    };\n'
  + '    const drawBackground = () => {\n'
  + '      if (!ctx) return;\n'
  + '      const rect = wrapper.getBoundingClientRect();\n'
  + '      const width = rect.width;\n'
  + '      const height = rect.height;\n'
  + '\n'
  + '      ctx.clearRect(0, 0, canvas.width, canvas.height);\n'
  + '\n'
  + '      if (kind === "lines") {\n'
  + '        const c: BackgroundConfigLines = (config as\n'
  + '          | BackgroundConfigLines\n'
  + '          | undefined) ?? {\n'
  + '          lineColor:\n'
  + '            mode === "dark"\n'
  + '              ? `rgba(255, 255, 255, 0.05)`\n'
  + '              : `rgba(0, 0, 0, 0.05)`,\n'
  + '        };\n'
  + '        drawLines(ctx, width, height, c);\n'
  + '      } else if (kind === "dots") {\n'
  + '        const c: BackgroundConfigDots = (config as\n'
  + '          | BackgroundConfigDots\n'
  + '          | undefined) ?? {\n'
  + '          dotColor:\n'
  + '            mode === "dark"\n'
  + '              ? `rgba(255, 255, 255, 0.15)`\n'
  + '              : `rgba(0, 0, 0, 0.15)`,\n'
  + '        };\n'
  + '        drawDots(ctx, width, height, c);\n'
  + '      } else if (kind === "chessboard") {\n'
  + '        const c: BackgroundConfigChessboard = (config as\n'
  + '          | BackgroundConfigChessboard\n'
  + '          | undefined) ?? {\n'
  + '          chessboardColor:\n'
  + '            mode === "dark"\n'
  + '              ? `rgba(255, 255, 255, 0.03)`\n'
  + '              : `rgba(0, 0, 0, 0.02)`,\n'
  + '        };\n'
  + '        drawChessboard(ctx, width, height, c);\n'
  + '      }\n'
  + '    };\n'
  + '\n'
  + '    resizeCanvas();\n'
  + '\n'
  + '    const resizeObserver = new ResizeObserver(() => {\n'
  + '      resizeCanvas();\n'
  + '    });\n'
  + '    resizeObserver.observe(wrapper);\n'
  + '\n'
  + '    return () => {\n'
  + '      resizeObserver.disconnect();\n'
  + '    };\n'
  + '  }, [mode, kind, config]);\n'
  + '\n'
  + '  const stx = jss.hash({\n'
  + '    "--backgroundWrapper-bgColor":\n'
  + '      mode === "dark" ? theme.colors.gray["800"] : "white",\n'
  + '  });\n'
  + '\n'
  + '  return (\n'
  + '    <div\n'
  + '      className={classNames(styles.backgroundWrapper, stx, className)}\n'
  + '      style={style}\n'
  + '      ref={wrapperRef}\n'
  + '    >\n'
  + '      <canvas ref={canvasRef} />\n'
  + '    </div>\n'
  + '  );\n'
  + '};\n'
  + '\n'
  + 'Background.displayName = "Background";\n'
  + '\n'
  + 'Background.Container = BackgroundContainer;\n'
  + '\n'
  + 'export type { BackgroundProps, BackgroundKind, BackgroundConfig };\n'
  + 'export { Background };\n'
